//ngebuild.com/\", \"telephone\": \"+66982799145\", \"logo\": {\"@type\": \"ImageObject\", \"url\": \"https://ngebuild.com/assets/nge-9b58beeb765ab627.png\"}, \"image\": \"https://ngebuild.com/og-nonthaburi.jpg\", \"foundingDate\": \"1985-11-05\", \"address\": {\"@type\": \"PostalAddress\", \"streetAddress\": \"98/72 หมู่บ้านกฤษดาลากูน\", \"addressLocality\": \"นนทบุรี\", \"addressRegion\": \"นนทบุรี\", \"postalCode\": \"11130\", \"addressCountry\": \"TH\"}, \"areaServed\": [{\"@type\": \"AdministrativeArea\", \"name\": \"นนทบุรี\"}, {\"@type\": \"AdministrativeArea\", \"name\": \"กรุงเทพมหานคร\"}, {\"@type\": \"AdministrativeArea\", \"name\": \"ปริมณฑล\"}], \"contactPoint\": {\"@type\": \"ContactPoint\", \"telephone\": \"+66982799145\", \"contactType\": \"customer service\", \"areaServed\": \"TH\", \"availableLanguage\": [\"th\"]}, \"sameAs\": [\"https://www.facebook.com/nextgenength/\", \"https://www.dataforthai.com/company/0103528028423/\"], \"hasMap\": \"https://maps.app.goo.gl/jKKSr42Ax6v7HqWRA\", \"openingHours\": \"Mo-Su 00:00-23:59\"}, {\"@type\": \"WebSite\", \"@id\": \"https://ngebuild.com/#website\", \"url\": \"https://ngebuild.com/\", \"name\": \"Next Gen Engineering\", \"inLanguage\": \"th-TH\", \"publisher\": {\"@id\": \"https://ngebuild.com/#organization\"}}, {\"@type\": \"AboutPage\", \"@id\": \"https://ngebuild.com/about\", \"url\": \"https://ngebuild.com/about\", \"name\": \"ประวัติบริษัท Next Gen Engineering\", \"description\": \"ประวัติ Next Gen Engineering ภายใต้ห้างหุ้นส่วนจำกัด รวมพลชัย เอ็นจิเนียริ่ง จดทะเบียนตั้งแต่ปี 2528 พร้อมประสบการณ์งานก่อสร้างกว่า 40 ปี\", \"inLanguage\": \"th-TH\", \"isPartOf\": {\"@id\": \"https://ngebuild.com/#website\"}, \"about\": {\"@id\": \"https://ngebuild.com/#organization\"}, \"breadcrumb\": {\"@id\": \"https://ngebuild.com/about#breadcrumb\"}}, {\"@type\": \"BreadcrumbList\", \"itemListElement\": [{\"@type\": \"ListItem\", \"position\": 1, \"name\": \"หน้าหลัก\", \"item\": \"https://ngebuild.com/\"}, {\"@type\": \"ListItem\", \"position\": 2, \"name\": \"ประวัติบริษัท\"}], \"@id\": \"https://ngebuild.com/about#breadcrumb\"}]}</script><script defer src=\"./site-config.js\"></script><script defer src=\"./site-shell.js\"></script><script defer src=\"./app.js\"></script><meta property=\"og:locale\" content=\"th_TH\"><meta property=\"og:site_name\" content=\"Next Gen Engineering\"><meta property=\"og:url\" content=\"https://ngebuild.com/about\"><meta name=\"twitter:card\" content=\"summary_large_image\"><meta name=\"twitter:title\" content=\"จากประสบการณ์กว่า 40 ปี สู่ Next Gen Engineering | NGE\"><meta name=\"twitter:description\" content=\"ประวัติ Next Gen Engineering ดำเนินงานภายใต้ห้างหุ้นส่วนจำกัด รวมพลชัย เอ็นจิเนียริ่ง จดทะเบียนตั้งแต่วันที่ 5 พฤศจิกายน พ.ศ. 2528 พร้อมประสบการณ์งานก่อสร้างกว่า 40 ปี\"><meta name=\"twitter:image\" content=\"https://ngebuild.com/og-nonthaburi.jpg\"><script defer src=\"/performance.js\"></script></head>\r\n<body data-page=\"about\"><a class=\"skip-link\" href=\"#main-content\">ข้ามไปเนื้อหาหลัก</a><nge-header></nge-header><main id=\"main-content\" class=\"about-ref-page\">\n  <section class=\"about-ref-intro\" aria-labelledby=\"about-title\">\n    <div class=\"container about-ref-intro-grid\">\n      <div class=\"about-ref-copy reveal\">\n        <span class=\"about-ref-kicker\">เกี่ยวกับเรา · NGE</span>\n        <h1 id=\"about-title\">ผู้รับเหมาที่เติบโต<br>จากหน้างานจริง</h1>\n        <i class=\"about-ref-rule\" aria-hidden=\"true\"></i>\n        <p><strong>Next Gen Engineering (NGE)</strong> ดำเนินงานภายใต้ <strong><a href=\"https://www.dataforthai.com/company/0103528028423/\" target=\"_blank\" rel=\"noopener noreferrer\">ห้างหุ้นส่วนจำกัด รวมพลชัย เอ็นจิเนียริ่ง</a></strong> จดทะเบียนตั้งแต่วันที่ 5 พฤศจิกายน พ.ศ. 2528 เราเริ่มต้นจากงานก่อสร้างจริง และทำงานต่อเนื่องมานานกว่า 40 ปี</p>\n        <p>ประสบการณ์จากบ้าน อาคาร โรงเรียน ร้านค้า งานต่อเติมและรีโนเวท ทำให้เราเข้าใจว่าแต่ละโครงการมีเงื่อนไขไม่เหมือนกัน งานทุกชิ้นจึงเริ่มจากการดูพื้นที่จริง คุยขอบเขตให้ชัด และวางลำดับงานก่อนลงมือ</p>\n        <p>วันนี้ NGE นำประสบการณ์เดิมมารวมกับการวางแผนที่เป็นระบบ เพื่อให้เจ้าของโครงการเห็นภาพงบประมาณ ขั้นตอน และความคืบหน้าได้ง่ายขึ้นตั้งแต่วันแรกจนส่งมอบ</p>\n        <div class=\"about-ref-actions\"><a class=\"btn btn-primary\" href=\"/projects\">ดูผลงานของเรา <svg><use href=\"#i-arrow\"/></svg></a><a class=\"about-ref-text-link\" href=\"./assets/NGE-Company-Profile.pdf\" download>ดาวน์โหลด Company Profile <svg><use href=\"#i-download\"/></svg></a></div>\n      </div>\n      <div class=\"about-ref-portrait reveal\">\n        <div class=\"about-ref-photo-main\"><img src=\"./assets/home-slider/construction-building-exterior-fast.webp\" alt=\"อาคารจากผลงานก่อสร้างของ Next Gen Engineering\" width=\"1280\" height=\"853\" fetchpriority=\"high\" decoding=\"async\"></div>\n        <div class=\"about-ref-engineer\" aria-hidden=\"true\"><span></span><img src=\"./assets/page-heroes/about-engineer-original-face-v3.png\" alt=\"\" width=\"1024\" height=\"1536\" decoding=\"async\"></div>\n        <div class=\"about-ref-years\"><b>40+</b><span>ปีของประสบการณ์<br>งานก่อสร้าง</span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"about-ref-expertise\" aria-labelledby=\"expertise-title\">\n    <div class=\"container\">\n      <div class=\"about-ref-section-head reveal\"><span>WHAT WE DO</span><h2 id=\"expertise-title\">งานที่เราดูแล</h2></div>\n      <div class=\"about-ref-service-grid\">\n        <article class=\"about-ref-service reveal\"><b>01</b><h3>รับเหมาก่อสร้างครบวงจร</h3><p>บ้าน อาคาร สำนักงาน ร้านค้า และอาคารสาธารณะ ตั้งแต่วางแผน ประเมินราคา จนถึงส่งมอบงาน</p><a href=\"/construction-near-me\">ดูบริการก่อสร้าง <svg><use href=\"#i-arrow\"/></svg></a></article>\n        <article class=\"about-ref-service reveal\"><b>02</b><h3>รีโนเวทและต่อเติม</h3><p>ปรับพื้นที่เดิมให้ใช้งานได้ดีขึ้น ตรวจสภาพก่อนเริ่ม แยกขอบเขตงาน และวางแผนให้กระทบการใช้งานน้อยที่สุด</p><a href=\"/renovation-service-nonthaburi\">ดูบริการรีโนเวท <svg><use href=\"#i-arrow\"/></svg></a></article>\n        <article class=\"about-ref-service reveal\"><b>03</b><h3>ออกแบบและควบคุมงาน</h3><p>ประสานแบบ โครงสร้าง สถาปัตยกรรม และงานระบบให้เดินไปในทิศทางเดียวกัน พร้อมรายงานความคืบหน้าอย่างชัดเจน</p><a href=\"/services\">ดูบริการออกแบบ <svg><use href=\"#i-arrow\"/></svg></a></article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"about-ref-journey\" aria-labelledby=\"journey-title\">\n    <div class=\"container\">\n      <div class=\"about-ref-journey-head reveal\"><span>OUR JOURNEY</span><h2 id=\"journey-title\">จากจุดเริ่มต้น — ปัจจุบัน</h2><p>เรื่องราวที่วัดจากงานที่ทำจริง มากกว่าคำโฆษณา</p></div>\n      <div class=\"about-ref-timeline\">\n        <article class=\"about-ref-era about-ref-era-left reveal\">\n          <figure><img src=\"./assets/projects/school-25/01-p01.webp\" alt=\"ผลงานก่อสร้างอาคารและโรงเรียนของบริษัท\" width=\"1200\" height=\"800\" loading=\"lazy\" decoding=\"async\"></figure>\n          <div class=\"about-ref-era-copy\"><span>พ.ศ. 2528</span><h3>จุดเริ่มต้นของกิจการ</h3><p>ห้างหุ้นส่วนจำกัด รวมพลชัย เอ็นจิเนียริ่ง จดทะเบียนเมื่อวันที่ 5 พฤศจิกายน พ.ศ. 2528 และเริ่มสร้างประสบการณ์จากงานก่อสร้างหลากหลายประเภท</p></div>\n        </article>\n        <article class=\"about-ref-era about-ref-era-right reveal\">\n          <figure><img src=\"./assets/projects/military-saraburi/04-p10.webp\" alt=\"ทีมก่อสร้างทำงานในโครงการอาคาร\" width=\"1200\" height=\"800\" loading=\"lazy\" decoding=\"async\"></figure>\n          <div class=\"about-ref-era-copy\"><span>ตลอด 40+ ปี</span><h3>โตจากโจทย์ที่ต่างกันในทุกหน้างาน</h3><p>บ้าน อาคารราชการ โรงเรียน ร้านค้า ร้านอาหาร งานระบบ และงานปรับปรุง ล้วนสอนให้เราตรวจข้อมูลก่อนตัดสินใจ และเลือกวิธีทำงานให้เหมาะกับพื้นที่จริง</p></div>\n        </article>\n        <article class=\"about-ref-era about-ref-era-left reveal\">\n          <figure><img src=\"./assets/projects/wichai-sriracha/02-p13.webp\" alt=\"งานก่อสร้างและปรับปรุงพื้นที่เชิงพาณิชย์\" width=\"1200\" height=\"800\" loading=\"lazy\" decoding=\"async\"></figure>\n          <div class=\"about-ref-era-copy\"><span>NEXT GEN ENGINEERING</span><h3>ประสบการณ์เดิม วิธีทำงานที่ชัดขึ้น</h3><p>เราต่อยอดความรู้ของทีมด้วยระบบวางแผน ประสานงาน และติดตามความคืบหน้า เพื่อให้แบบ งบประมาณ และหน้างานอยู่ในภาพเดียวกัน</p></div>\n        </article>\n        <article class=\"about-ref-era about-ref-era-right reveal\">\n          <figure><img src=\"./assets/projects/lake-legend/01-p23.webp\" alt=\"ผลงานบ้านพักอาศัยของ Next Gen Engineering\" width=\"1200\" height=\"800\" loading=\"lazy\" decoding=\"async\"></figure>\n          <div class=\"about-ref-era-copy\"><span>วันนี้</span><h3>ดูแลตั้งแต่ก่อนเริ่มจนส่งมอบ</h3><p>รับงานก่อสร้าง รีโนเวท ต่อเติม บิ้วอิน โครงสร้าง และงานระบบในนนทบุรี กรุงเทพฯ และปริมณฑล โดยมีทีมช่วยเรียบเรียงโจทย์ให้เริ่มต้นได้ง่าย</p></div>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"about-ref-values\" aria-labelledby=\"values-title\">\n    <div class=\"container about-ref-values-grid\">\n      <div class=\"about-ref-values-title reveal\"><span>หลักการทำงาน</span><h2 id=\"values-title\">ชัดเจนตั้งแต่คุย<br>จนถึงส่งมอบ</h2><p>เพราะงานก่อสร้างมีรายละเอียดเยอะ หน้าที่ของเราคือทำให้เรื่องยากกลายเป็นเรื่องที่ลูกค้าตามได้</p></div>\n      <div class=\"about-ref-values-list\">\n        <article class=\"reveal\"><b>01</b><div><h3>สำรวจจากพื้นที่จริง</h3><p>ไม่รีบสรุปก่อนเห็นสภาพหน้างาน แบบเดิม และข้อจำกัดที่เกี่ยวข้อง</p></div></article>\n        <article class=\"reveal\"><b>02</b><div><h3>ขอบเขตและราคาอ่านเข้าใจ</h3><p>แยกรายการสำคัญให้ตรวจสอบได้ ลดจุดคลุมเครือก่อนเริ่มงาน</p></div></article>\n        <article class=\"reveal\"><b>03</b><div><h3>ติดตามความคืบหน้าได้</h3><p>สื่อสารลำดับงาน ประเด็นที่ต้องตัดสินใจ และสิ่งที่จะทำต่ออย่างตรงไปตรงมา</p></div></article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"about-ref-profile\"><div class=\"container about-ref-profile-inner reveal\"><div><small>COMPANY PROFILE</small><h2>รู้จักทีมและผลงานของเราให้มากขึ้น</h2><p>รวมประวัติกิจการ ขอบเขตบริการ ผลงานอ้างอิง บุคลากร และแนวทางดำเนินโครงการ</p></div><a class=\"btn btn-primary\" href=\"./assets/NGE-Company-Profile.pdf\" download><svg><use href=\"#i-download\"/></svg> ดาวน์โหลด PDF</a></div></section>\n  <section class=\"closing-cta\"><div class=\"container\"><div><span>มีแบบ มีพื้นที่ หรือยังไม่รู้จะเริ่มตรงไหน</span><h2>ส่งข้อมูลมาให้ทีมช่วยดูได้เลย</h2></div><a class=\"btn btn-dark\" href=\"/contact\">คุยเรื่องโครงการ <svg><use href=\"#i-arrow\"/></svg></a></div></section>\n</main><nge-footer></nge-footer></body></html>\n","boq-construction-guide.html":"<!doctype html>\r\n<html lang=\"th\"><head>\r\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#f5a400\">\r\n  <title>BOQ งานก่อสร้างคืออะไร อ่านยังไงก่อนเซ็นสัญญา | NGE</title>\r\n  <meta name=\"description\" content=\"คู่มืออ่าน BOQ งานก่อสร้างสำหรับเจ้าของโครงการ ดูขอบเขต ปริมาณ หน่วย ราคา วัสดุ งานไม่รวม และวิธีเทียบใบเสนอราคาให้ตรงกันก่อนตัดสินใจ\"><meta name=\"robots\" content=\"index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1\"><meta name=\"author\" content=\"Next Gen Engineering\">\r\n  <link rel=\"canonical\" href=\"https://ngebuild.com/boq-construction-guide\"><link rel=\"alternate\" hreflang=\"th-TH\" href=\"https://ngebuild.com/boq-construction-guide\">\r\n  <meta property=\"og:type\" content=\"article\"><meta property=\"og:locale\" content=\"th_TH\"><meta property=\"og:site_name\" content=\"Next Gen Engineering\"><meta property=\"og:title\" content=\"BOQ งานก่อสร้างคืออะไร อ่านยังไงก่อนเซ็นสัญญา | NGE\"><meta property=\"og:description\" content=\"คู่มืออ่าน BOQ งานก่อสร้างสำหรับเจ้าของโครงการ ดูขอบเขต ปริมาณ หน่วย ราคา วัสดุ งานไม่รวม และวิธีเทียบใบเสนอราคาให้ตรงกันก่อนตัดสินใจ\"><meta property=\"og:url\" content=\"https://ngebuild.com/boq-construction-guide\"><meta property=\"og:image\" content=\"https://ngebuild.com/og-ngebuild-cover-2026.jpg\">\r\n  <meta name=\"twitter:card\" content=\"summary_large_image\"><meta name=\"twitter:title\" content=\"BOQ งานก่อสร้างคืออะไร อ่านยังไงก่อนเซ็นสัญญา | NGE\"><meta name=\"twitter:description\" content=\"คู่มืออ่าน BOQ งานก่อสร้างสำหรับเจ้าของโครงการ ดูขอบเขต ปริมาณ หน่วย ราคา วัสดุ งานไม่รวม และวิธีเทียบใบเสนอราคาให้ตรงกันก่อนตัดสินใจ\"><meta name=\"twitter:image\" content=\"https://ngebuild.com/og-ngebuild-cover-2026.jpg\">\r\n  <link rel=\"icon\" type=\"image/png\" href=\"./assets/nge-9b58beeb765ab627.png\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Anuphan:wght@400;500;600;700&family=Sarabun:wght@300;400;500;600&display=swap\" rel=\"preload\" as=\"style\" data-async-fonts><noscript><link href=\"https://fonts.googleapis.com/css2?family=Anuphan:wght@400;500;600;700&family=Sarabun:wght@300;400;500;600&display=swap\" rel=\"stylesheet\"></noscript><link rel=\"stylesheet\" href=\"./styles.min.css\">\r\n  <script type=\"application/ld+json\">{\"@context\": \"https://schema.org\", \"@graph\": [{\"@type\": [\"Organization\", \"GeneralContractor\"], \"@id\": \"https://ngebuild.com/#organization\", \"name\": \"Next Gen Engineering\", \"alternateName\": \"NGE\", \"legalName\": \"ห้างหุ้นส่วนจำกัด รวมพลชัย เอ็นจิเนียริ่ง\", \"url\": \"https://ngebuild.com/\", \"telephone\": \"+66982799145\", \"logo\": {\"@type\": \"ImageObject\", \"url\": \"https://ngebuild.com/assets/nge-9b58beeb765ab627.png\"}, \"image\": \"https://ngebuild.com/og-nonthaburi.jpg\", \"foundingDate\": \"1985-11-05\", \"address\": {\"@type\": \"PostalAddress\", \"streetAddress\": \"98/72 หมู่บ้านกฤษดาลากูน\", \"addressLocality\": \"นนทบุรี\", \"addressRegion\": \"นนทบุรี\", \"postalCode\": \"11130\", \"addressCountry\": \"TH\"}, \"areaServed\": [{\"@type\": \"AdministrativeArea\", \"name\": \"นน